BASE = f'{F}/release-candidate-target/release/caliper-docgen'
NEW = os.environ.get('NEW_BIN', f'{F}/collapse-default/target/release/caliper-docgen')
OUT = f'{F}/collapse-default/out'
CORPORA = {
    'chakra-corpus': f'{F}/corpora/chakra-ui/packages/react/src',
    'chakra-only': f'{F}/checker-default/chakra-only/src',
    'gate-large': f'{F}/gate-large/src',
    'shadcn-ui': f'{F}/corpora/shadcn-ui/apps/v4',
    'react-spectrum': f'{F}/corpora/react-spectrum/packages',
    'mantine': f'{F}/corpora/mantine/packages/@mantine/core/src',
    'ant-design': f'{F}/corpora/ant-design/components',
}
LIMIT_KB = 14 * 1024 * 1024


def run(binary, src, extra, path):
    with open(path, 'w') as out:
        proc = subprocess.Popen([binary, 'extract', '--src', src, '--quiet', '--no-cache', *extra], stdout=out,
                                stderr=subprocess.DEVNULL)
        peak = 0
        while proc.poll() is None:
            rss = subprocess.run(['ps', '-o', 'rss=', '-p', str(proc.pid)], capture_output=True, text=True).stdout
            peak = max(peak, int(rss.strip() or 0))
            if peak > LIMIT_KB:
                proc.kill()
                proc.wait()
                return {'killed': True, 'peak_mib': peak // 1024}
            time.sleep(0.5)
    return {'exit': proc.returncode, 'peak_mib': peak // 1024, 'bytes': os.path.getsize(path)}


def load(path):
    text = open(path).read()
    return json.loads(text[text.index('{'):])


def props_stats(doc):
    counts = [len(c.get('props', {})) for c in doc['components'].values()]
    return {'components': len(counts), 'median': statistics.median(counts) if counts else 0,
            'max': max(counts) if counts else 0, 'total': sum(counts)}


def strip(doc):
    doc = dict(doc)
    doc.pop('stats', None)
    return doc


def button_argtypes(binary, src, extra, name):
    path = f'{OUT}/{name}.rdt.json'
    meta = run(binary, src, ['--format', 'rdt', *extra], path)
    if meta.get('killed') or meta.get('exit'):
        return meta
    doc = load(path)
    hits = {}
    for comp in doc.values():
        if comp.get('displayName') == 'Button' and comp['filePath'].endswith('components/button/button.tsx'):
            kept = [p for p in comp['props'].values() if not (
                p.get('parent') and p['parent']['name'] in ('Attributes', 'RefAttributes', 'ClassAttributes')
                and 'node_modules' in p['parent']['fileName'])]
            hits[comp['filePath']] = {'rdt_props': len(comp['props']), 'argtypes': len(kept)}
    return hits


def main():
    os.makedirs(OUT, exist_ok=True)
    result_path, names = sys.argv[1], sys.argv[2:]
    results = json.load(open(result_path)) if os.path.exists(result_path) else {}
    for name in names:
        src = CORPORA[name]
        row = {}
        runs = [('new', NEW, [])]
        if name != 'chakra-corpus':  # the unfixed 0.11.0 binary is not run there (42 GB)
            runs = [('base', BASE, []), ('base_none', BASE, ['--collapse-inherited-props', 'none'])] + runs
        docs = {}
        for label, binary, extra in runs:
            path = f'{OUT}/{name}.{label}.json'
            meta = run(binary, src, ['--json', *extra], path)
            if not meta.get('killed') and meta.get('exit') == 0:
                docs[label] = load(path)
                meta.update(props_stats(docs[label]))
            row[label] = meta
            print(name, label, meta, flush=True)
        if 'base' in docs and 'new' in docs:
            row['identical_to_base_default'] = strip(docs['base']) == strip(docs['new'])
            changed = [k for k in docs['new']['components']
                       if docs['base']['components'].get(k) != docs['new']['components'][k]]
            row['components_changed'] = len(changed)
            row['changed_examples'] = changed[:5]
        if name == 'chakra-corpus':
            row['button_new'] = button_argtypes(NEW, src, [], f'{name}.new')
        results[name] = row
        json.dump(results, open(result_path, 'w'), indent=1)


main()

