"""Props listed per component from saved outputs: a component's `props` holds ids of prop sets (name -> prop id) or of
single props. Prints per corpus and label: JSON MB, components, median/max/total listed props, layered members."""
import json, os, statistics, sys

OUT = '/Users/gabe/Projects/caliper-fixtures/collapse-default/out'


def listed(doc, comp):
    n = 0
    for ref in comp['props']:
        if ref in doc.get('propSets', {}):
            n += len(doc['propSets'][ref])
        else:
            n += 1
    return n


for name in sys.argv[1:]:
    for label in ('base', 'base_none', 'new'):
        path = f'{OUT}/{name}.{label}.json'
        if not os.path.exists(path):
            continue
        text = open(path).read()
        doc = json.loads(text[text.index('{'):])
        counts = [listed(doc, c) for c in doc['components'].values()]
        layered = sum(len(doc['nameLists'][layer['members']]) for c in doc['components'].values()
                      for layer in c.get('inheritance', []) if layer.get('members'))
        print(f"{name:15} {label:9} {len(text) / 1e6:9.2f} MB  comps {len(counts):5}  median {statistics.median(counts):6}"
              f"  max {max(counts):5}  total {sum(counts):8}  layered-members {layered}")

